package com.kai.automusic;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.provider.DocumentsContract;import android.database.Cursor;import android.widget.*;import org.json.*;import java.util.*;
public class MainActivity extends Activity {
 android.content.SharedPreferences p; LinearLayout root; TextView list; ArrayList<String> songs=new ArrayList<>();
 public void onCreate(Bundle b){super.onCreate(b);p=getSharedPreferences("music",0);try{JSONArray a=new JSONArray(p.getString("songs","[]"));for(int i=0;i<a.length();i++)songs.add(a.getString(i));}catch(Exception e){} ScrollView s=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(24,24,24,24);s.addView(root);setContentView(s);TextView title=new TextView(this);title.setText("Kai Auto Music • v1.0");title.setTextSize(26);root.addView(title);button("+ Add files",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(i,1);});button("+ Add folder (recursive)",()->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE),2));toggle("Auto play on charging","auto",true);toggle("Pause on unplug","unplug",true);toggle("Shuffle","shuffle",false);toggle("Repeat playlist","repeat",true);toggle("Start after reboot","boot",true);button("Enable automation / arm",()->send("ARM"));button("Play",()->send("PLAY"));button("Pause",()->send("PAUSE"));button("Next",()->send("NEXT"));button("Disable automation",()->{p.edit().putBoolean("armed",false).apply();stopService(new Intent(this,PlayerService.class));});button("Clear playlist",()->{songs.clear();save();send("PAUSE");});list=new TextView(this);root.addView(list);refresh();}
 void button(String t,Runnable r){Button b=new Button(this);b.setText(t);root.addView(b);b.setOnClickListener(v->r.run());}void toggle(String t,String k,boolean d){Switch s=new Switch(this);s.setText(t);s.setChecked(p.getBoolean(k,d));root.addView(s);s.setOnCheckedChangeListener((v,c)->p.edit().putBoolean(k,c).apply());}
 void send(String a){Intent i=new Intent(this,PlayerService.class).setAction(a);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}
 String name(Uri u){try(Cursor c=getContentResolver().query(u,new String[]{"_display_name"},null,null,null)){if(c!=null&&c.moveToFirst())return c.getString(0);}catch(Exception e){}return u.toString();}
 void add(Uri u,String n){if(n.toLowerCase(Locale.ROOT).matches(".*\\.(mp3|mp4|wav|wave|flac|m4a|aac|ogg|opus|3gp|mkv|webm|amr)$")&&!songs.contains(u.toString()))songs.add(u.toString());}
 void walk(Uri tree,String id){Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,id);try(Cursor c=getContentResolver().query(children,new String[]{"document_id","_display_name","mime_type"},null,null,null)){while(c!=null&&c.moveToNext()){String child=c.getString(0);if(DocumentsContract.Document.MIME_TYPE_DIR.equals(c.getString(2)))walk(tree,child);else add(DocumentsContract.buildDocumentUriUsingTree(tree,child),c.getString(1));}}}
 protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(result!=RESULT_OK||data==null)return;try{if(r==2){Uri u=data.getData();getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);walk(u,DocumentsContract.getTreeDocumentId(u));}else if(data.getClipData()!=null){for(int i=0;i<data.getClipData().getItemCount();i++)pick(data.getClipData().getItemAt(i).getUri());}else pick(data.getData());save();}catch(Exception e){Toast.makeText(this,e.toString(),Toast.LENGTH_LONG).show();}}
 void pick(Uri u){getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);add(u,name(u));}void save(){p.edit().putString("songs",new JSONArray(songs).toString()).apply();refresh();}void refresh(){StringBuilder b=new StringBuilder("Playlist: "+songs.size()+" files\n");for(String u:songs)b.append(name(Uri.parse(u))).append('\n');list.setText(b);}
}